add('title','AI &amp; Machine Learning · Lesson 7','Clustering','<div class="cover-layout"><div><p class="eyebrow">Find structure without supplied labels.</p><h1 class="search-title grad">Discover the<br>shape of data.</h1><p class="cover-sub">K-means · Mixtures · Hierarchies · PCA</p></div>'+diagram('cover')+'</div><div class="chapter-strip"><span>01 · Group observations</span><span>02 · Model uncertainty</span><span>03 · Find useful directions</span></div>','Final course lecture. All eight original Plotly resources are retained locally, including all five original K-means animation frames. Added labs use the original observations.','cover-slide')
add('map','The road ahead','Four views of the same question',cols(card('Centroids','<p>Represent each group by a typical location.</p>'),card('Distributions','<p>Express membership with probabilities.</p>','stat'),card('Hierarchies','<p>Build groups at several resolutions.</p>','comp'),card('Directions','<p>Describe variation with a new basis.</p>','cyber'))+note('Clustering groups observations. PCA transforms features; it does not assign clusters.'))
add('unlabeled','01 · What changes?','The labels are no longer supplied',cols(card('Classification','<p>Learn a relationship between features x and observed labels y.</p>'),card('Clustering','<p>Use features x to propose groups. Their interpretation comes afterward.</p>','stat'))+note('Similarity depends on the chosen features, their scale, and the algorithm.'))
lab('data-lab','Look for structure in the original observations','source','Pan, zoom and inspect the 240 original points. No cluster labels are supplied.','Original kmeans_data.json, all coordinates retained.','kmeans_data')
add('meaning','01 · Define similarity','A cluster is a useful modeling choice',cols(card('Within a group','<p>Observations should be similar under the chosen representation.</p>'),card('Across groups','<p>Groups should differ in a way that matters for the task.</p>','comp'))+note('A visible pattern does not prove that the data has one true or natural partition.'),'Internal scores, stability and domain knowledge can evaluate unlabeled results. External labels, when available for evaluation, provide another perspective.')
add('centroids','02 · K-means','Represent K groups with K centroids',math('μₖ ∈ ℝᵐ  rᵢₖ ∈ {0,1}  Σₖ rᵢₖ = 1')+cols(card('Centroid μₖ','<p>A location in feature space. It need not equal any observation.</p>'),card('Membership rᵢₖ','<p>A one-hot row: exactly one cluster receives value 1.</p>','stat'))+note('Choose K before fitting this model. Cluster numbers are arbitrary names.'))
add('objective','02 · The distortion objective','Minimize squared distances within clusters',math('J(μ,r) = Σᵢ Σₖ rᵢₖ ‖xᵢ − μₖ‖²')+cols(card('Fix the centroids','<p>Assign each point to its nearest centroid.</p>'),card('Fix the assignments','<p>Replace each centroid with its assigned points’ mean.</p>','stat'))+note('Each exact step cannot increase J. Alternation need not reach the global minimum.'))
add('assign','02 · Assignment step','Choose the nearest centroid',math('rᵢₖ = 1 if k = argminⱼ ‖xᵢ − μⱼ‖²')+diagram('assign')+note('Break equal-distance ties consistently. The added lab chooses the lowest centroid index.'))
add('update','02 · Mean update','The derivative explains why the mean appears',math('∂J/∂μₖ = 2 Σᵢ rᵢₖ(μₖ − xᵢ)<br>μₖ = (Σᵢ rᵢₖ xᵢ) / (Σᵢ rᵢₖ)')+note('An empty cluster has no defined mean. An implementation must explicitly handle that case.'),'Corrects the sign of the source derivative. The stationary mean remains the same. The added trace retains an empty center; none of its displayed runs needs this fallback.')
lab('source-animation','Replay the course’s K-means animation','frames','Use Step, Play or the frame selector. All five original snapshots are preserved.','Original kmeans_steps.json data and all five frames. Frame numbers are source snapshot indices, not our new half-step trace.','kmeans_steps')
lab('kmeans-lab','Separate assignment from centroid movement','kmeans','Change K or initialization, then Step through the two operations. Watch the distortion.','Added Lloyd trace on the original 240 points: K=2,3,4; seeds 0,7,19; 79 states in total. Each update and assignment is separate. Final objectives independently checked with sklearn KMeans.')
add('initialization','02 · Initialization and stopping','The same data can lead to different endpoints',cols(card('Initialization','<p>Try several starts. K-means++ spreads initial centers using squared distances.</p>'),card('Stopping','<p>Stop when assignments stabilize, center movement is small, or the budget is reached.</p>','comp'))+note('Compare converged objectives for the same K and preprocessing. A lower objective is not automatically a better domain interpretation.'))
add('limits','02 · Know the geometry','K-means favors compact Euclidean groups',cols(card('Sensitive to','<p>Feature units, outliers, initialization, and the chosen K.</p>','cyber'),card('Can struggle with','<p>Curved groups, elongated distributions, and strongly different densities.</p>','comp'))+note('Changing the representation changes what “nearest” means.'))
add('choose-k','03 · How many groups?','The objective alone cannot choose K',math('J*ₖ₊₁ ≤ J*ₖ  and  J*ₙ = 0')+note('These are statements about optimal distortion. Separate local fits may not form a perfectly decreasing curve.'),'Splitting a cluster cannot increase the globally optimal squared-error objective. If every observation has its own center, distortion is zero. That does not make n clusters useful.')
lab('elbow-source','Inspect the original elbow curve','source','Hover over the supplied distortion values. Look for diminishing returns as K increases.','Original elbow.json, including its highlighted point and all ten supplied distortion values. Source fitting settings are not supplied.','elbow')
add('elbow','03 · A heuristic, not a verdict','An elbow suggests a tradeoff',cols(card('Before the bend','<p>Another centroid explains a substantial amount of remaining spread.</p>'),card('After the bend','<p>Extra centroids mostly refine existing groups.</p>','stat'))+note('Some curves have no clear bend. Combine this heuristic with other evidence.'))
add('silhouette','03 · Silhouette','Compare cohesion with the nearest other group',math('a(i) = mean distance to other points in its cluster<br>b(i) = smallest mean distance to another cluster<br>s(i) = [b(i) − a(i)] / max{a(i), b(i)}')+note('Use s(i)=0 for a singleton; the score requires 2 to n−1 nonempty clusters.'),'This deck uses ordinary Euclidean distances, the standard default. The source writes squared distances; that is a different dissimilarity choice and produces different numerical scores. When both a and b are zero, use zero.')
add('silhouette-reading','03 · Read the score','Silhouette is a geometric diagnostic',table(['Value','Interpretation'],[['Near +1','Much closer, on average, to its own group'],['Near 0','Similar average distances to two groups'],['Below 0','Closer on average to another group']])+note('Average over observations for each candidate K. A high value does not establish semantic truth.'))
lab('selection-lab','Compare K using the same fitted partitions','selection','Choose K to inspect its partition, distortion and Euclidean silhouette.','Added sklearn KMeans fits K=1…10, 30 starts each, random_state=42, raw source points. The new curve is distinguished from the original elbow resource.')
lab('silhouette-lab','Inspect silhouette one observation at a time','silhouette','Select a point and K. Compare a(i), b(i), and its signed silhouette score.','Added exact Euclidean silhouette explorer using the preceding fitted partitions. Browser values checked against sklearn silhouette_samples for all observations and K=2…10.')
add('soft','04 · Gaussian mixtures','Replace one-hot assignments with responsibilities',cols(card('Hard membership',math('rᵢ = (0, 1, 0)')+'<p>Each point belongs to one cluster.</p>'),card('Soft membership',math('rᵢ = (0.15, 0.70, 0.15)')+'<p>Nonnegative probabilities sum to one.</p>','stat'))+note('Mixture membership is conditional on the fitted model, not a supplied ground-truth label.'))
add('gaussian','04 · Component geometry','A Gaussian needs a mean and a covariance',math('p(x | z=k) = N(x; μₖ, Σₖ)')+diagram('ellipses')+note('For the ordinary full-dimensional density, Σₖ must be positive definite.'),'A covariance is generally positive semidefinite; an invertible covariance is required by the standard nonsingular Gaussian density. Regularization prevents singular fitted components.')
add('mixture','04 · Combine the components','Mix densities with nonnegative weights',math('p(x) = Σₖ πₖ N(x; μₖ, Σₖ)<br>πₖ ≥ 0  Σₖ πₖ = 1')+cols(card('πₖ','<p>Prior probability of selecting component k.</p>'),card('p(x)','<p>A density; its value need not be between zero and one.</p>','comp')))
add('posterior','04 · Bayes’ rule for memberships','Normalize each component’s weighted density',math('rᵢₖ = πₖ N(xᵢ; μₖ, Σₖ) / Σⱼ πⱼ N(xᵢ; μⱼ, Σⱼ)')+note('A hard assignment can be recovered with argmaxₖ rᵢₖ. Overlap remains visible in the full probability vector.'))
add('likelihood','04 · Fit the model','Maximize the observed-data log likelihood',math('ℓ(θ) = Σᵢ log[Σₖ πₖ N(xᵢ; μₖ, Σₖ)]')+cols(card('Unknown parameters','<p>Means, covariances, and mixture weights.</p>'),card('Unknown memberships','<p>Responsibilities depend on those same parameters.</p>','stat'))+note('The dependence is circular. Iterate between estimating memberships and updating parameters.'))
add('em','05 · Expectation–maximization','Use the current model to improve the next one',diagram('em')+math('Q(θ | θold) = E<sub>Z | X,θold</sub>[log p(X,Z | θ)]')+note('The E-step evaluates the posterior; the M-step maximizes expected complete-data log likelihood.'),'Corrects wording that suggests taking an expectation of likelihood rather than log likelihood. Exact EM has a nondecreasing observed likelihood, but not a global-optimum guarantee.')
add('mstep','05 · Weighted sufficient statistics','The M-step is a soft version of averaging',math('Nₖ = Σᵢ rᵢₖ  πₖ = Nₖ/n<br>μₖ = (Σᵢ rᵢₖ xᵢ)/Nₖ<br>Σₖ = [Σᵢ rᵢₖ(xᵢ−μₖ)(xᵢ−μₖ)ᵀ]/Nₖ')+note('Use the newly updated mean in the covariance formula. Each observation contributes fractionally.'))
lab('gmm-lab','Watch EM reshape three Gaussian components','gmm','Step through fitted EM iterations and select an observation to inspect its responsibilities.','Added full-covariance, three-component EM on all original 240 points. Forty updates; diagonal covariance regularization 10⁻⁶. Ellipses are one Mahalanobis-radius contours, not 68% regions in 2D. Soft probabilities update for the chosen point.')
add('em-limits','05 · What convergence does not promise','A rising likelihood still needs interpretation',cols(card('Local solutions','<p>Use multiple starts and inspect the fitted components.</p>'),card('Degenerate components','<p>A covariance can collapse around an observation. Regularization is essential in practice.</p>','cyber'))+note('Select component counts with a suitable criterion such as BIC or held-out likelihood, alongside domain evidence.'))
add('em-kmeans','05 · Connect the algorithms','K-means is related to a limiting mixture model',cols(card('Gaussian-mixture EM','<p>Soft responsibilities; covariance and weight updates.</p>','stat'),card('K-means / Lloyd','<p>Hard nearest-center assignments; arithmetic means.</p>'))+note('Equal spherical covariances and a small-variance limit recover the K-means assignment rule.'),'Ordinary Lloyd K-means is not literally unrestricted Gaussian-mixture EM. Describe it as a hard-assignment or small-variance connection rather than conflating the two algorithms.')
add('hierarchical','06 · Hierarchical clustering','Build a family of nested groups',diagram('hierarchy')+note('Start with singletons, merge the closest clusters, and repeat until one remains.'))
lab('dendrogram-source','Read the course’s original dendrogram','source','Inspect the six observations and their supplied merge heights side by side.','Original hc_dendogram.json: all points, labels, branch coordinates and heights retained. Layout and contrast corrected. The supplied tree matches average linkage on these observations.','hc_dendogram')
add('cut','06 · From a tree to a partition','Choose a height, then cut across the tree',cols(card('Below the cut','<p>Observations already connected form a group.</p>'),card('Above the cut','<p>Later merges are excluded from the chosen partition.</p>','stat'))+note('A hierarchy postpones the choice of resolution. It does not remove that choice.'))
add('linkage','06 · Define distance between groups','The linkage rule changes the tree',table(['Linkage','Between-cluster dissimilarity'],[['Single','Minimum pairwise distance'],['Complete','Maximum pairwise distance'],['Average','Mean of every cross-cluster pair distance'],['Centroid','Distance between the two cluster means']])+note('Centroid linkage can produce height inversions. A simple horizontal-cut interpretation then needs care.'),'Average linkage weights each observation pair equally. It is not the same as equally averaging distances between merged clusters regardless of their sizes.')
lab('hierarchy-lab','Change the linkage and the merge budget','hierarchy','Choose a linkage, then move through the five merges. The points and tree show the same partition.','Added exact SciPy linkages on the six source points. Merge-count selection is valid even for centroid inversions. Shows the resulting cluster count and most recent merge height.')
add('hierarchy-limits','06 · Tradeoffs','A tree makes structure inspectable',cols(card('Useful for','<p>Nested relationships and comparing several resolutions.</p>','stat'),card('Be careful with','<p>Irreversible greedy merges, scaling, outliers, and pairwise-distance storage.</p>','cyber'))+note('Single linkage can chain groups through a narrow bridge of nearby points.'))
add('pca-intro','07 · Principal component analysis','Change the coordinate system',cols(card('Clustering','<p>Groups observations into subsets.</p>'),card('PCA','<p>Finds orthogonal directions ordered by explained variance.</p>','comp'))+note('A high-variance direction may contain useful signal, nuisance variation, or both.'))
lab('aligned-lab','Start with variation aligned to an axis','source','Inspect the original Gaussian sample. Compare its horizontal and vertical spread.','Original gaussian_points.json, all 300 observations retained. Equal axis units preserve geometry.','gaussian_points')
lab('rotated-lab','The largest variation can lie between the axes','source','Inspect the source’s rotated Gaussian sample. A new direction can describe its spread.','Original gaussian_points_rot30.json, all 300 observations retained.','gaussian_points_rot30')
add('center','07 · Center before projecting','Subtract the mean and measure covariance',math('x̄ = (1/n) Σᵢ xᵢ  xᶜᵢ = xᵢ − x̄<br>S = [1/(n−1)] Σᵢ xᶜᵢ(xᶜᵢ)ᵀ')+note('The sample mean uses n. The unbiased sample covariance uses n−1.'),'Corrects the source mean denominator n−1. This deck consistently uses sample covariance (ddof=1), including its added PCA variance calculations.')
add('variance','07 · Choose a direction','Maximize variance with a unit vector',math('tᵢ = uᵀ(xᵢ−x̄)  Var(t) = uᵀSu<br>maximize uᵀSu subject to uᵀu = 1')+note('Without the unit-length constraint, scaling u would increase projected variance without bound.'))
add('eigen','07 · Solve the constrained problem','The answer is an eigenvector',math('L(u,λ) = uᵀSu − λ(uᵀu−1)<br>∂L/∂u = 0 ⇒ Su = λu')+cols(card('First component','<p>Choose the eigenvector with the largest eigenvalue.</p>'),card('Next components','<p>Choose orthogonal eigenvectors in descending eigenvalue order.</p>','stat'))+note('The sign of an eigenvector is arbitrary. Repeated eigenvalues can make the basis nonunique.'))
lab('pca-lab','Rotate a projection and find the first component','pca','Move the angle, toggle projection lines, or select Best PC. Track explained variance and reconstruction error.','Added live centered 2D PCA projection on either original 300-point Gaussian dataset. Sample variance and squared reconstruction error computed directly. Best PC comes from independent NumPy eigh.')
add('reconstruct','07 · Compress and reconstruct','Keep d directions, then map back approximately',math('tᵢ = Uᵀd(xᵢ − x̄)<br>x̂ᵢ = x̄ + Ud tᵢ<br>Explained variance ratio = (Σⱼ≤d λⱼ) / (Σⱼ≤m λⱼ)')+note('For centered data and a fixed dimension, PCA minimizes squared linear reconstruction error.'),'Ud has orthonormal columns. Explained variance is not predictive accuracy or evidence that discarded directions are irrelevant to a downstream task.')
add('applications','07 · Applications and limits','A compact representation can serve several tasks',cols(card('Compression','<p>Retain the leading scores and reconstruct approximately.</p>'),card('Visualization','<p>Plot two or three scores to inspect broad linear structure.</p>','comp'),card('Preprocessing','<p>Reduce dimensions or transform the covariance structure.</p>','stat'))+note('PCA is linear. Nonlinear visualizations answer different questions and are not universally better.'))
lab('scale-source','Feature units can dominate a distance','source','Compare the ranges of the two original features before any transformation.','Original two_gaussian_blobs.json: both 300-point groups retained. Source colors identify generating groups only for illustration, not labels supplied to a clustering fit.','two_gaussian_blobs')
add('scaling','08 · Preprocessing','Rescaling does not make a feature Gaussian',table(['Transform','Feature j becomes','Effect'],[['Min–max','(xⱼ−minⱼ)/(maxⱼ−minⱼ)','Training range becomes [0,1]'],['Standardize','(xⱼ−meanⱼ)/sdⱼ','Zero mean and unit variance'],['PCA whitening','Λ⁻¹ᐟ²Uᵀ(x−x̄)','Decorrelates and rescales retained PCs']])+note('Handle constant features and zero eigenvalues. Fit preprocessing on development/training data only.'),'Standardization does not turn an arbitrary distribution into a normal distribution. New observations can lie outside a fitted min–max range. Sample vs population variance conventions must be stated.')
lab('preprocessing-lab','Compare every original preprocessing panel','panel','Switch among the four original views. Pan, zoom and inspect all 600 observations in each.','Original two_gaussian_blobs_panel.json: every coordinate in all eight traces retained. Four panels are presented one at a time to keep labels and geometry legible; axes use equal units. Source transformations are shown as supplied.','two_gaussian_blobs_panel')
add('whitening','08 · Understand whitening','Identity covariance comes at a price',math('z = Λ⁻¹ᐟ²Uᵀ(x−x̄) ⇒ Cov(z) = I')+cols(card('Useful effect','<p>Remove linear correlation and equalize retained component variances.</p>','stat'),card('Tradeoff','<p>Discard relative variance scales and potentially amplify small-variance noise.</p>','cyber'))+note('Uncorrelated does not mean independent in general. Whitening is a choice, not a mandatory cleanup step.'),'The identity assumes positive retained eigenvalues and a consistent covariance convention. A truncated transform whitens only the retained subspace.')
add('workflow','Bring the methods together','Make the representation and the grouping explicit','<ol class="steps"><li>Choose features and a distance that reflect the task.</li><li>Inspect units, missingness, outliers, and possible preprocessing.</li><li>Compare algorithms, initializations, and resolutions.</li><li>Check internal scores, stability, and domain usefulness.</li><li>Document what each group means—and what remains uncertain.</li></ol>')
add('practice','Check your understanding','Five questions to connect the ideas','<ol class="exercise-list"><li>Why can distortion alone not choose K?</li><li>What is the difference between πₖ and rᵢₖ?</li><li>What does changing a linkage rule change?</li><li>Why does PCA require a unit-length direction?</li><li>Does standardization make a variable Gaussian?</li></ol>')
add('answers','Check your understanding','The distinctions that matter',table(['Question','Answer'],[['Choosing K','More optimal centroids cannot increase distortion.'],['Prior vs posterior','πₖ is a component weight; rᵢₖ conditions on observation i.'],['Linkage','It changes between-group distances and the resulting merge tree.'],['Unit direction','It prevents variance from increasing just by scaling u.'],['Standardization','It changes location and scale, not distributional shape.']]))
add('summary','The ideas to keep','Structure depends on the question you ask',cols(card('K-means','<p>Compact groups around learned means.</p>'),card('Mixtures','<p>Probabilistic memberships and flexible covariance.</p>','stat'),card('Hierarchies','<p>Nested partitions across resolutions.</p>','comp'),card('PCA','<p>Orthogonal directions of large variance.</p>','cyber'))+note('Useful structure is supported by geometry, checks, and the purpose of the analysis.'))
add('references','Sources and further reading','Course resources and technical references',bullets('<a href="https://www.aretor.it/courses/aiml2526/lessons/07_clustering/">Alessandro Torcinovich · Clustering course resource</a>','<a href="https://www.statlearning.com/">James et al. · An Introduction to Statistical Learning · Chapter 12</a>','<a href="https://www.microsoft.com/en-us/research/publication/pattern-recognition-machine-learning/">Bishop · Pattern Recognition and Machine Learning · Chapters 9 and 12</a>','<a href="https://scikit-learn.org/stable/modules/clustering.html">scikit-learn · Clustering</a> · <a href="https://scikit-learn.org/stable/modules/mixture.html">Mixtures</a> · <a href="https://scikit-learn.org/stable/modules/decomposition.html">PCA</a> · <a href="https://scikit-learn.org/stable/modules/preprocessing.html">Preprocessing</a>')+note('All interactive assets are local. The source map records original resources, added experiments, and corrections.'))
